private GenericUrl buildTargetUrl(String path) {
  GenericUrl genericUrl = new GenericUrl(translate.getBaseUrl() + "v3/" + path);
  if (options.getApiKey() != null) {
    genericUrl.put("key", options.getApiKey());
  }
  return genericUrl;
}

@Override
public List<List<DetectedLanguage>> detect(List<String> texts) {
  try {
    List<List<DetectedLanguage>> allDetections = new java.util.ArrayList<>();
    for (String text : texts) {
      DetectLanguageRequest request = new DetectLanguageRequest();
      request.setContent(text);
      String parent = options.getParent();
      if (parent == null) {
        parent = "projects/" + options.getProjectId();
      }
      DetectedLanguage detection =
          translate.projects().detectLanguage(parent, request).execute().getLanguages().get(0);
      java.util.List<DetectedLanguage> detections = new java.util.ArrayList<>();
      if (detection != null) {
        detections.add(detection);
      }
      allDetections.add(detections);
    }
    return allDetections;
  } catch (IOException ex) {
    throw translate(ex);
  }
}

