          firstNonNull(Option.TARGET_LANGUAGE.getString(optionMap), options.getTargetLanguage());
      final String sourceLanguage = Option.SOURCE_LANGUAGE.getString(optionMap);
      String parent = options.getParent();
      if (parent == null) {
        parent = "projects/" + options.getProjectId() + "/locations/" + targetLanguage;
      }
      TranslateTextRequest request = new TranslateTextRequest();
      request.setContents(texts);
      request.setMimeType(Option.FORMAT.getString(optionMap));
      request.setSourceLanguageCode(sourceLanguage);
      request.setTargetLanguageCode(targetLanguage);
      String model = Option.MODEL.getString(optionMap);
      if (model != null) {
        request.setModel(model);
      }
      List<Translation> translations =
          translate
              .projects()
              .locations()
              .translateText(parent, request)
              .execute()
              .getTranslations();
      return Lists.transform(
          translations != null ? translations : ImmutableList.<Translation>of(),
